const HEADING = /^(#{2,})\s+(.+?)\s*$/;
// A rule's lead-in is bolded, and long ones wrap, so the closing ** may sit
// several lines below the bullet marker.
const LEAD_IN = /\*\*([\s\S]+?)\*\*/;

